-- DayFlow database schema
-- Run this once in Supabase: SQL Editor > New query > paste > Run.
-- Safe to re-run: it only creates what's missing.

-- ─── Tables ──────────────────────────────────────────────────────────────────
-- Every row belongs to a user (user_id). Ids are generated by the app, so the
-- primary key is (user_id, id).

create table if not exists public.categories (
  user_id uuid not null references auth.users(id) on delete cascade,
  id      text not null,
  name    text not null,
  color   text not null,
  icon    text not null default '',
  primary key (user_id, id)
);

create table if not exists public.events (
  user_id              uuid not null references auth.users(id) on delete cascade,
  id                   text not null,
  title                text not null,
  date                 text not null,            -- "YYYY-MM-DD"
  start_time           text not null,            -- "HH:MM"
  end_time             text not null default '',
  color                text not null,
  category             text not null default '',
  details              text not null default '',
  completed            boolean not null default false,
  subtasks             jsonb not null default '[]'::jsonb,
  recurrence           jsonb,                    -- repeat rule, null = does not repeat
  recurrence_overrides jsonb,                    -- per-occurrence edits/deletes
  gcal_id              text,
  gcal_sync            boolean not null default false,
  primary key (user_id, id)
);
create index if not exists events_user_date_idx on public.events (user_id, date);

create table if not exists public.daily_notes (
  user_id   uuid not null references auth.users(id) on delete cascade,
  id        text not null,
  title     text not null default '',
  date      text not null,
  details   text not null default '',
  subtasks  jsonb not null default '[]'::jsonb,
  gcal_id   text,
  gcal_sync boolean not null default false,
  primary key (user_id, id)
);
create index if not exists daily_notes_user_date_idx on public.daily_notes (user_id, date);

create table if not exists public.user_settings (
  user_id uuid primary key references auth.users(id) on delete cascade,
  theme   text not null default 'default',
  is_dark boolean not null default false
);

-- ─── Row Level Security ──────────────────────────────────────────────────────
-- Each signed-in user can only see and change their own rows.

alter table public.categories    enable row level security;
alter table public.events        enable row level security;
alter table public.daily_notes   enable row level security;
alter table public.user_settings enable row level security;

drop policy if exists "own rows" on public.categories;
create policy "own rows" on public.categories for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own rows" on public.events;
create policy "own rows" on public.events for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own rows" on public.daily_notes;
create policy "own rows" on public.daily_notes for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own rows" on public.user_settings;
create policy "own rows" on public.user_settings for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ─── Permissions for the API ─────────────────────────────────────────────────
grant select, insert, update, delete on public.categories    to authenticated;
grant select, insert, update, delete on public.events        to authenticated;
grant select, insert, update, delete on public.daily_notes   to authenticated;
grant select, insert, update, delete on public.user_settings to authenticated;
